contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint extraEth) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= extraEth);
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        address owner = c.owner(); if (__ESBMC_reverted()) return;
        uint beforeOwnerBal = owner.balance;
        uint beforeBalance = address(c).balance;
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterOwnerBal = owner.balance;
        assert(!reverted && afterBalance == 0 && afterDeposits == beforeDeposits && afterOwnerBal == beforeOwnerBal + beforeBalance);
    }
    receive() external payable {}
}

