pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 extraEth) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= extraEth);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        address owner;
        try c.owner() returns (address __r) { owner = __r; } catch { return; }
        uint beforeOwnerBal = owner.balance;
        uint beforeBalance = address(c).balance;
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        uint afterBalance = address(c).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterOwnerBal = owner.balance;
        assertTrue(!reverted && afterBalance == 0 && afterDeposits == beforeDeposits && afterOwnerBal == beforeOwnerBal + beforeBalance);
    }

    function testFuzz_run(uint256 extraEth) public {
        _run(extraEth);
    }

    receive() external payable {}
}
